def _with_mock_fallback(mock_key: str):
    """装饰器：API 调用失败时自动降级到 Mock 数据。"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            g = _get_github()
            if g is None:
                print(f"[github/client] 未配置 Token，使用 Mock 数据")
                return _load_mock()[mock_key]
            try:
                return func(g, *args, **kwargs)
            except GithubException as e:
                print(f"[github/client] API 错误 (HTTP {e.status})，降级到 Mock 数据")
                return _load_mock()[mock_key]
        return wrapper
    return decorator
